// email-queue.module.ts
import { Module } from '@nestjs/common';
import { BullModule } from '@nestjs/bullmq';
import { EmailProcessor } from './email.processor';
import { NewsletterProducerService } from './newsletter-producer.service';
import { ResetPasswordProducerService } from './reset-password-producer.service';

@Module({
  imports: [
    // Single shared queue for ALL email work. BullMQ keeps waiting jobs
    // in a Redis sorted set scored by `priority`, so at pop time the
    // worker always pulls the smallest-priority (most urgent) waiting job.
    BullModule.registerQueue({
      name: 'emailQueue',
    }),
  ],
  providers: [EmailProcessor, NewsletterProducerService, ResetPasswordProducerService],
  exports: [NewsletterProducerService, ResetPasswordProducerService],
})
export class EmailQueueModule {}

// email.processor.ts
import { Processor, WorkerHost } from '@nestjs/bullmq';
import { Logger } from '@nestjs/common';
import { Job } from 'bullmq';

interface EmailJobData {
  to: string;
  templateId: string;
}

// Worker slot count = 1 (concurrency: 1). Only one job can be IN FLIGHT
// at any moment; the handler runs synchronously-to-completion with no
// interrupt/preempt mechanism once a job enters process().
@Processor('emailQueue', { concurrency: 1 })
export class EmailProcessor extends WorkerHost {
  private readonly logger = new Logger(EmailProcessor.name);

  async process(job: Job<EmailJobData>): Promise<void> {
    this.logger.log(`Started job ${job.id} (name=${job.name}, priority=${job.opts.priority})`);

    if (job.name === 'newsletter') {
      // Simulates the ~30s of real work (template render + SMTP send) per bulk email.
      await this.sleep(30_000);
    } else if (job.name === 'reset-password') {
      // Urgent job's own work is fast once it actually starts.
      await this.sleep(200);
    }

    this.logger.log(`Finished job ${job.id} (name=${job.name})`);
  }

  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

// newsletter-producer.service.ts
import { Injectable } from '@nestjs/common';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';

@Injectable()
export class NewsletterProducerService {
  constructor(@InjectQueue('emailQueue') private readonly emailQueue: Queue) {}

  // Enqueues a large burst of bulk jobs, all LOW priority (higher number = lower urgency).
  async enqueueNewsletterBurst(recipients: string[], templateId: string): Promise<void> {
    for (const to of recipients) {
      await this.emailQueue.add(
        'newsletter',
        { to, templateId },
        { priority: 10 },
      );
    }
  }
}

// reset-password-producer.service.ts
import { Injectable } from '@nestjs/common';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';

@Injectable()
export class ResetPasswordProducerService {
  constructor(@InjectQueue('emailQueue') private readonly emailQueue: Queue) {}

  // Enqueued with priority: 1 — the highest priority BullMQ supports —
  // on the assumption this alone guarantees the job jumps ahead and
  // starts almost immediately, regardless of what else is happening.
  async enqueueResetPasswordEmail(to: string, templateId: string): Promise<void> {
    await this.emailQueue.add(
      'reset-password',
      { to, templateId },
      { priority: 1 },
    );
  }
}

